            var existingSlugs = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var m in meta)
                existingSlugs.Add(m.Slug);

            var allMeta = meta.ToList();
            foreach (var rm in ContentRoadmapMeta.GetMissingFrom(existingSlugs))
                allMeta.Add((rm.Slug, rm.Title, rm.Desc, rm.Cat, rm.Tool, null, null));

            foreach (var m in allMeta)
            {
                var body = GuideBodies.Get(m.Slug);
                if (body == null) continue;
                var roadmap = ContentRoadmapIndex.Get(m.Slug);
                var cluster = roadmap?.Cluster;
                var (author, reviewer) = SiteAuthors.ResolveForContent(m.Slug, m.Cat);
                var (fq, fa) = ContentGuideSeo.ResolveFaqs(m.Slug, cluster, m.Tool, m.Fq, m.Fa);
                yield return new ContentEntry
                {
                    Slug = m.Slug,
                    Title = m.Title,
                    Description = m.Desc,
                    Category = m.Cat,
                    Cluster = cluster,
                    ToolUrl = m.Tool,
                    BodyHtml = body,
                    Published = new DateTime(2025, 6, 1),
                    LastReviewed = ContentGuideSeo.LastReviewedFor(m.Slug, cluster, m.Cat),
                    Kind = ContentKind.Guide,
                    AuthorSlug = author,
                    ReviewerSlug = reviewer,
                    Sources = ContentSourcesCatalog.GetForSlug(m.Slug),
                    FaqQuestions = fq,
                    FaqAnswers = fa,
                    HowToSteps = GuideHowToSteps.Get(m.Slug)?.ToArray(),
                };
            }
        }

